// Expected output: system ok\n
pub fn main(mut world: World) {
    let args = world.args();
    let path = String::from_utf8(args[0].clone()).unwrap();
    let mut directory = world.directory(&path).unwrap();
    directory.create_directory("one").unwrap();
    let mut file = directory.create("one/input").unwrap();
    file.write_all(b"data").unwrap();
    drop(file);
    directory.rename("one/input", "one/renamed").unwrap();
    let mut one = directory.open_directory("one").unwrap();
    let names = one.list().unwrap();
    assert_eq!(names.len(), 1);
    assert_eq!(names[0], "renamed".as_bytes().to_vec());
    assert!(directory.create_directory("../escape").is_err());
    assert!(directory.rename("one/renamed", "../escaped").is_err());
    assert!(one.__lkjscript_create_directory(b"../escape\0") < 0);
    directory.remove("one/renamed").unwrap();
    drop(one);
    directory.remove_directory("one").unwrap();
    assert!(directory.list().unwrap().is_empty());

    let mut clock = world.clock();
    let start = clock.nanoseconds().unwrap();
    let mut short = [0u8; 8];
    assert_eq!(clock.__lkjscript_read(&mut short), -22);
    let mut shell_directory = world.directory("/bin").unwrap();
    let executable = shell_directory.open("sh").unwrap();
    let mut input = world.temporary_file().unwrap();
    let mut output = world.temporary_file().unwrap();
    let mut errors = world.temporary_file().unwrap();
    let mut result = world.temporary_file().unwrap();
    input.write_all(b"input\n").unwrap();
    input.rewind().unwrap();
    let mut process = world.process();
    let arguments = vec!["-c".as_bytes().to_vec(), "cat; printf error >&2; printf result >&3; exit 7".as_bytes().to_vec()];
    let mut child = process.spawn_file(&executable, &arguments, &input, &output, &errors, &result).unwrap();
    assert_eq!(child.wait().unwrap(), 7);
    assert!(child.wait().is_err());
    let mut duplicate = output.duplicate().unwrap();
    duplicate.rewind().unwrap();
    assert_eq!(duplicate.read_to_end().unwrap(), "input\n".as_bytes().to_vec());
    output.rewind().unwrap();
    errors.rewind().unwrap();
    result.rewind().unwrap();
    assert_eq!(output.read_to_end().unwrap(), "input\n".as_bytes().to_vec());
    assert_eq!(errors.read_to_end().unwrap(), "error".as_bytes().to_vec());
    assert_eq!(result.read_to_end().unwrap(), "result".as_bytes().to_vec());
    let arguments = vec!["-c".as_bytes().to_vec(), "while :; do :; done".as_bytes().to_vec()];
    let mut child = process.spawn_file(&executable, &arguments, &input, &output, &errors, &result).unwrap();
    assert!(child.try_wait().unwrap().is_none());
    child.terminate().unwrap();
    assert_eq!(child.wait().unwrap(), 137);
    let child = process.spawn_file(&executable, &arguments, &input, &output, &errors, &result).unwrap();
    drop(child);
    let malformed = vec![vec![0u8]];
    assert!(process.spawn_file(&executable, &malformed, &input, &output, &errors, &result).is_err());
    let mut bad = world.temporary_file().unwrap();
    bad.write_all(b"not an executable").unwrap();
    bad.set_executable().unwrap();
    let no_arguments: Vec<Vec<u8>> = Vec::new();
    assert!(process.spawn_file(&bad, &no_arguments, &input, &output, &errors, &result).is_err());
    let self_executable = world.executable().unwrap();
    drop(self_executable);
    assert!(clock.nanoseconds().unwrap() >= start);
    let mut output = world.stdout();
    output.write(b"system ok\n");
}
